"use client";

import { useState } from "react";

const API = process.env.NEXT_PUBLIC_API_URL || "https://corps-admission-rotation-postal.trycloudflare.com";

export default function Home() {
  const [job, setJob] = useState({
      title: "Data Analyst",
          jd_text: "Looking for Python, SQL, Excel, Pandas and Power BI skills.",
              must_have: "python,sql,excel,pandas",
                  nice_to_have: "power bi,tableau",
                      min_exp_years: 1,
                          location: "Remote"
                            });
                              const [jobId, setJobId] = useState("JOB001");
                                const [candidateId, setCandidateId] = useState("CAND001");
                                  const [candidateName, setCandidateName] = useState("Aarav Shah");
                                    const [file, setFile] = useState(null);
                                      const [results, setResults] = useState([]);
                                        const [message, setMessage] = useState("");

                                          async function createJob(e) {
                                              e.preventDefault();
                                                  try {
                                                        const res = await fetch(API + "/api/job/create", {
                                                                method: "POST",
                                                                        headers: { "Content-Type": "application/json" },
                                                                                body: JSON.stringify({ ...job, min_exp_years: Number(job.min_exp_years) })
                                                                                      });
                                                                                            const data = await res.json();
                                                                                                  if (!res.ok) throw new Error(data.detail || "Job creation failed");
                                                                                                        setJobId(data.job_id);
                                                                                                              setMessage("Job created: " + data.job_id);
                                                                                                                  } catch (err) {
                                                                                                                        setMessage("Error: " + err.message);
                                                                                                                            }
                                                                                                                              }

                                                                                                                                async function uploadResume(e) {
                                                                                                                                    e.preventDefault();
                                                                                                                                        if (!file) {
                                                                                                                                              setMessage("Please select a resume file.");
                                                                                                                                                    return;
                                                                                                                                                        }
                                                                                                                                                            const form = new FormData();
                                                                                                                                                                form.append("candidate_name", candidateName);
                                                                                                                                                                    form.append("file", file);
                                                                                                                                                                        try {
                                                                                                                                                                              const res = await fetch(API + "/api/resume/upload/" + candidateId, {
                                                                                                                                                                                      method: "POST",
                                                                                                                                                                                              body: form
                                                                                                                                                                                                    });
                                                                                                                                                                                                          const data = await res.json();
                                                                                                                                                                                                                if (!res.ok) throw new Error(data.detail || "Upload failed");
                                                                                                                                                                                                                      setMessage("Resume uploaded successfully for " + candidateName);
                                                                                                                                                                                                                          } catch (err) {
                                                                                                                                                                                                                                setMessage("Error: " + err.message);
                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                        async function rankCandidates() {
                                                                                                                                                                                                                                            try {
                                                                                                                                                                                                                                                  const res = await fetch(API + "/api/rank/" + jobId, { method: "POST" });
                                                                                                                                                                                                                                                        const data = await res.json();
                                                                                                                                                                                                                                                              if (!res.ok) throw new Error(data.detail || "Ranking failed");
                                                                                                                                                                                                                                                                    setResults(data);
                                                                                                                                                                                                                                                                          setMessage("Candidate ranking completed.");
                                                                                                                                                                                                                                                                              } catch (err) {
                                                                                                                                                                                                                                                                                    setMessage("Error: " + err.message);
                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                            return (
                                                                                                                                                                                                                                                                                                <main style={{ maxWidth: 1050, margin: "35px auto", padding: 20, fontFamily: "Arial, sans-serif", color: "#172033" }}>
                                                                                                                                                                                                                                                                                                      <h1>Automated Resume Screening</h1>
                                                                                                                                                                                                                                                                                                            <p>Recruiter Dashboard | AI-assisted candidate matching</p>
                                                                                                                                                                                                                                                                                                                  {message && <p style={{ padding: 12, background: "#e8f3ff", borderRadius: 8 }}>{message}</p>}

                                                                                                                                                                                                                                                                                                                        <section style={{ padding: 20, border: "1px solid #ddd", borderRadius: 12, marginTop: 24 }}>
                                                                                                                                                                                                                                                                                                                                <h2>Create a Job</h2>
                                                                                                                                                                                                                                                                                                                                        <form onSubmit={createJob}>
                                                                                                                                                                                                                                                                                                                                                  <p>Job title</p>
                                                                                                                                                                                                                                                                                                                                                            <input style={field} value={job.title} onChange={e => setJob({ ...job, title: e.target.value })} />
                                                                                                                                                                                                                                                                                                                                                                      <p>Job description</p>
                                                                                                                                                                                                                                                                                                                                                                                <textarea style={field} rows={3} value={job.jd_text} onChange={e => setJob({ ...job, jd_text: e.target.value })} />
                                                                                                                                                                                                                                                                                                                                                                                          <p>Required skills (comma separated)</p>
                                                                                                                                                                                                                                                                                                                                                                                                    <input style={field} value={job.must_have} onChange={e => setJob({ ...job, must_have: e.target.value })} />
                                                                                                                                                                                                                                                                                                                                                                                                              <p>Nice-to-have skills</p>
                                                                                                                                                                                                                                                                                                                                                                                                                        <input style={field} value={job.nice_to_have} onChange={e => setJob({ ...job, nice_to_have: e.target.value })} />
                                                                                                                                                                                                                                                                                                                                                                                                                                  <p>Minimum experience (years)</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                            <input style={field} type="number" min="0" value={job.min_exp_years} onChange={e => setJob({ ...job, min_exp_years: e.target.value })} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                      <p>Location</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                <input style={field} value={job.location} onChange={e => setJob({ ...job, location: e.target.value })} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <button style={btn} type="submit">Create Job</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </form>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </section>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <section style={{ padding: 20, border: "1px solid #ddd", borderRadius: 12, marginTop: 24 }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <h2>Upload a Resume</h2>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <form onSubmit={uploadResume}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <p>Candidate ID</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <input style={field} value={candidateId} onChange={e => setCandidateId(e.target.value)} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <p>Candidate name</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <input style={field} value={candidateName} onChange={e => setCandidateName(e.target.value)} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <p>Resume file (PDF, DOCX or TXT)</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <input style={field} type="file" accept=".pdf,.docx,.txt" onChange={e => setFile(e.target.files?.[0] || null)} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <button style={btn} type="submit">Upload Resume</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </form>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </section>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <section style={{ padding: 20, border: "1px solid #ddd", borderRadius: 12, marginTop: 24 }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <h2>Rank Candidates</h2>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <p>Job ID</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <input style={field} value={jobId} onChange={e => setJobId(e.target.value)} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <button style={btn} onClick={rankCandidates}>Rank Candidates</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {results.map((c, i) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <article key={c.candidate_id} style={{ borderTop: "1px solid #ddd", padding: 16, marginTop: 16 }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <h3>{i + 1}. {c.candidate_name}</h3>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <p>Score: <strong>{c.score}</strong></p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <p>Experience: {c.years_experience} years</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <p>Matched skills: {c.matched_skills.join(", ") || "None"}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <p>Missing skills: {c.missing_skills.join(", ") || "None"}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <p>{c.reasons}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </article>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <p style={{ fontSize: 13, color: "#555" }}>Scores are matching aids, not automatic hiring decisions. Human review is required.</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </section>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </main>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const field = {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          display: "block",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            width: "100%",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              boxSizing: "border-box",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                padding: 11,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  border: "1px solid #bbb",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    borderRadius: 6,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      marginBottom: 12
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const btn = {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        padding: "11px 20px",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          background: "#174ea6",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            color: "white",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              border: 0,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                borderRadius: 6,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  cursor: "pointer",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    marginTop: 8
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    };
